# ── Colormap class ──────────────────────────────────────────────

class _Colormap:
    """A callable colormap that maps scalar values [0,1] to RGBA tuples."""

    def __init__(self, name):
        self.name = name
        self.N = 256
        self._plotly_name = _CMAP_TO_PLOTLY.get(name, name)
        self._stops = _CMAP_STOPS.get(name, [(68,1,84), (33,145,140), (253,231,37)])

    def __call__(self, value, alpha=None, bytes=False):
        """Map a scalar or array of scalars in [0,1] to RGBA tuples."""
        if isinstance(value, _np.ndarray):
            out = _np.array([self._single(float(v)) for v in value.ravel()]).reshape(value.shape + (4,))
            if alpha is not None:
                out[..., 3] = alpha
            if bytes:
                return (_np.clip(out, 0, 1) * 255).astype(_np.uint8)
            return out
        if hasattr(value, '__iter__') and not isinstance(value, str):
            out = _np.array([self._single(float(v)) for v in value])
            if alpha is not None:
                out[:, 3] = alpha
            if bytes:
                return (_np.clip(out, 0, 1) * 255).astype(_np.uint8)
            return out
        rgba = self._single(float(value))
        if alpha is not None:
            rgba = rgba[:3] + (alpha,)
        if bytes:
            return tuple(int(c * 255) for c in rgba)
        return rgba

    def _single(self, v):
        """Map a single float in [0,1] to (r, g, b, a) with values in [0,1]."""
        v = max(0.0, min(1.0, v))
        stops = self._stops
        n = len(stops) - 1
        idx = v * n
        i = min(int(idx), n - 1)
        t = idx - i
        r = (stops[i][0] * (1 - t) + stops[i+1][0] * t) / 255.0
        g = (stops[i][1] * (1 - t) + stops[i+1][1] * t) / 255.0
        b = (stops[i][2] * (1 - t) + stops[i+1][2] * t) / 255.0
        return (r, g, b, 1.0)

    def reversed(self, name=None):
        """Return a reversed copy of this colormap."""
        rname = name or self.name + '_r'
        cmap = _Colormap(rname)
        cmap._stops = list(reversed(self._stops))
        cmap._plotly_name = self._plotly_name
        return cmap

    def resampled(self, lutsize):
        """Return a resampled copy."""
        cmap = _Colormap(self.name)
        cmap.N = lutsize
        cmap._stops = self._stops
        cmap._plotly_name = self._plotly_name
        return cmap

    @property
    def plotly_colorscale(self):
        return self._plotly_name

    def __str__(self):
        return self.name

    def __repr__(self):
        return f"<matplotlib.cm._Colormap '{self.name}'>"

    def __eq__(self, other):
        if isinstance(other, _Colormap):
            return self.name == other.name
        return NotImplemented

    def __hash__(self):
        return hash(self.name)


# Aliases
Colormap = _Colormap
LinearSegmentedColormap = _Colormap
ListedColormap = _Colormap

# ── Public API ──────────────────────────────────────────────────

# Global colormap registry
_cmap_registry = {}


def _ensure_registry():
    """Lazily populate the registry on first use."""
    if _cmap_registry:
        return
    # Register every known colormap name
    all_names = set(list(_CMAP_TO_PLOTLY.keys()) + list(_CMAP_STOPS.keys()))
    for name in all_names:
        _cmap_registry[name] = _Colormap(name)
        # Also register _r (reversed) variants
        rname = name + '_r'
        _cmap_registry[rname] = _cmap_registry[name].reversed(rname)


def get_cmap(name='viridis', lut=None):
    """Return a colormap object by name."""
    if isinstance(name, _Colormap):
        return name
    _ensure_registry()
    name = str(name)
    if name in _cmap_registry:
        cmap = _cmap_registry[name]
        if lut is not None:
            return cmap.resampled(lut)
        return cmap
    # Unknown name — create on the fly
    return _Colormap(name)


def register_cmap(name=None, cmap=None, **kwargs):
    """Register a colormap in the registry."""
    _ensure_registry()
    if cmap is not None:
        if name is None:
            name = cmap.name
        _cmap_registry[name] = cmap
    elif name is not None:
        _cmap_registry[name] = _Colormap(name)


def to_plotly(name):
    """Convert a matplotlib colormap name to its plotly equivalent string.
    Plotly 6.x accepts lowercase colorscale names."""
    if isinstance(name, _Colormap):
        pname = name.plotly_colorscale
        return pname.lower() if isinstance(pname, str) else pname
    result = _CMAP_TO_PLOTLY.get(str(name), str(name))
    return result.lower() if isinstance(result, str) else result


def to_rgba(value, cmap='viridis', alpha=None):
    """Convenience: map scalar(s) in [0,1] to RGBA via named colormap."""
    cm = get_cmap(cmap)
    return cm(value, alpha=alpha)


import sys as _sys

_cm_warned = set()

def _cm_getattr_fallback(self, name):
    if name.startswith('_'):
        raise AttributeError(name)
    key = f'{type(self).__name__}.{name}'
    if key not in _cm_warned:
        _cm_warned.add(key)
        try:
            _sys.__stderr__.write(
                f"[mpl-shim] cm.{key}() not implemented — returning None\n")
        except Exception:
            pass
    def _noop(*args, **kwargs): return None
    return _noop


class ScalarMappable:
    """Lightweight ScalarMappable for colorbar/legend support."""
    __getattr__ = _cm_getattr_fallback

    def __init__(self, norm=None, cmap=None):
        self.norm = norm
        self.cmap = get_cmap(cmap) if isinstance(cmap, str) else (cmap or get_cmap())
        self._A = None
        self._clim = (None, None)
        self.colorbar = None
        self.callbacks = type('_CB', (), {
            'process': lambda *a, **kw: None,
            'connect': lambda *a, **kw: 0,
            'disconnect': lambda *a, **kw: None,
        })()

    def set_array(self, A):
        self._A = A
    def get_array(self):
        return self._A
    def get_cmap(self):
        return self.cmap
    def set_cmap(self, cmap):
        self.cmap = get_cmap(cmap) if isinstance(cmap, str) else cmap
    def get_norm(self):
        return self.norm
    def set_norm(self, norm):
        self.norm = norm
    def get_clim(self):
        return self._clim
    def set_clim(self, vmin=None, vmax=None):
        if vmax is None and hasattr(vmin, '__len__'):
            vmin, vmax = vmin[0], vmin[1]
        self._clim = (vmin, vmax)
        if self.norm is not None and vmin is not None:
            try: self.norm.vmin = vmin
            except Exception: pass
        if self.norm is not None and vmax is not None:
            try: self.norm.vmax = vmax
            except Exception: pass

    def to_rgba(self, x, alpha=None, bytes=False):
        x = _np.asarray(x, dtype=float)
        if self.norm is not None:
            x = self.norm(x)
        return self.cmap(x, alpha=alpha, bytes=bytes)

    def changed(self):
        if self.callbacks is not None:
            try: self.callbacks.process('changed', self)
            except Exception: pass

    def autoscale(self):
        if self._A is not None and self.norm is not None:
            try:
                self.norm.autoscale(self._A)
                self._clim = (self.norm.vmin, self.norm.vmax)
            except Exception: pass

    def autoscale_None(self):
        if self._A is not None and self.norm is not None:
            try:
                self.norm.autoscale_None(self._A)
                self._clim = (self.norm.vmin, self.norm.vmax)
            except Exception: pass


# ── Module-level colormap attributes ───────────────────────────
# This makes cm.viridis, cm.plasma, cm.jet, etc. work as callables.

class _CmapModule:
    """Proxy that exposes every registered colormap as an attribute."""

    def __getattr__(self, name):
        if name.startswith('_'):
            raise AttributeError(name)
        _ensure_registry()
        if name in _cmap_registry:
            return _cmap_registry[name]
        # Try creating on the fly
        cmap = _Colormap(name)
        _cmap_registry[name] = cmap
        return cmap

    def __dir__(self):
        _ensure_registry()
        return list(_cmap_registry.keys()) + ['get_cmap', 'to_plotly', 'to_rgba',
                'ScalarMappable', 'register_cmap', 'Colormap',
                'LinearSegmentedColormap', 'ListedColormap']


# ─── Added: missing public names from upstream cm.py ──────────────


class ColormapRegistry(dict):
    """Read/write dict-like registry of colormaps. Mirrors upstream's
    :class:`matplotlib.cm.ColormapRegistry`: ``__getitem__`` returns the
    cmap, ``register`` adds one, ``unregister`` removes one (only for
    user-registered cmaps; the built-ins are protected)."""

    _BUILTIN_NAMES = set()

    def __init__(self, cmaps):
        super().__init__(cmaps)
        self._BUILTIN_NAMES = set(cmaps.keys())

    def __call__(self, name):
        return self[name]

    def __getitem__(self, name):
        _ensure_registry()
        if name in self:
            return super().__getitem__(name)
        if name in _cmap_registry:
            return _cmap_registry[name]
        raise KeyError(f"{name!r} is not a known colormap name")

    def register(self, cmap, *, name=None, force=False):
        nm = name or getattr(cmap, 'name', None)
        if nm is None:
            raise ValueError("registering a colormap requires a name")
        if nm in self._BUILTIN_NAMES and not force:
            raise ValueError(f"{nm!r} is a built-in colormap; pass force=True"
                             " to override")
        self[nm] = cmap
        _cmap_registry[nm] = cmap

    def unregister(self, name):
        if name in self._BUILTIN_NAMES:
            raise ValueError(f"cannot unregister built-in {name!r}")
        self.pop(name, None)
        _cmap_registry.pop(name, None)


def unregister_cmap(name):
    """Remove a user-registered colormap from the registry. Raises
    ``ValueError`` if ``name`` is a built-in (matches upstream)."""
    _ensure_registry()
    if name not in _cmap_registry:
        return
    # Detect built-ins as anything in the original mapping tables.
    if name in _CMAP_TO_PLOTLY or name in _CMAP_STOPS:
        raise ValueError(f"cannot unregister built-in colormap {name!r}")
    del _cmap_registry[name]


# Lazily-initialised module-level registry mirroring upstream's
# ``matplotlib.colormaps`` / ``matplotlib.cm._colormaps``. Callers can
# do ``cm._colormaps['viridis']`` for the same dict-style access.
_colormaps = None


def _get_colormaps():
    global _colormaps
    if _colormaps is None:
        _ensure_registry()
        _colormaps = ColormapRegistry(dict(_cmap_registry))
    return _colormaps


# Convenience alias matching the upstream re-export.
colormaps = _get_colormaps()


import sys as _sys
# Replace this module with the proxy so attribute access works
_self = _sys.modules[__name__]
_proxy = _CmapModule()
# Copy all public names to the proxy
for _k in list(vars(_self).keys()):
    if not _k.startswith('__'):
        try:
            setattr(_proxy, _k, getattr(_self, _k))
        except (AttributeError, TypeError):
            pass

# Keep original module accessible for function resolution
_proxy.__name__ = __name__
_proxy.__file__ = __file__
_proxy.__package__ = __package__
_proxy.__spec__ = getattr(_self, '__spec__', None)
_proxy.__path__ = getattr(_self, '__path__', [])
_proxy.__loader__ = getattr(_self, '__loader__', None)
_sys.modules[__name__] = _proxy


# ─── Added: ScalarMappable setters/getters (final) ──────────────────


def _sm_get_alpha(self):  return getattr(self, '_alpha', None)
def _sm_set_alpha(self, alpha): self._alpha = alpha
def _sm_get_clim(self):
    if self.norm is None: return (None, None)
    return (getattr(self.norm, 'vmin', None), getattr(self.norm, 'vmax', None))
def _sm_set_clim(self, vmin=None, vmax=None):
    if self.norm is not None:
        if vmin is not None: self.norm.vmin = vmin
        if vmax is not None: self.norm.vmax = vmax
def _sm_set_norm(self, norm): self.norm = norm

# `norm` already exists as instance attr — also expose as property for
# upstream-style `sm.norm = SomeNorm()` callers.
@property
def _sm_norm_prop(self):
    return self._sm_norm if hasattr(self, '_sm_norm') else self.__dict__.get('norm')
@_sm_norm_prop.setter
def _sm_norm_prop(self, v):
    self.__dict__['norm'] = v

ScalarMappable.get_alpha = _sm_get_alpha
ScalarMappable.set_alpha = _sm_set_alpha
ScalarMappable.get_clim  = _sm_get_clim
ScalarMappable.set_clim  = _sm_set_clim
ScalarMappable.set_norm  = _sm_set_norm


# ─── Added: stub methods to match upstream class surface ────────
def _attach_remaining_stubs():
    def _stub(self, *a, **kw): return None
    if not hasattr(ColormapRegistry, 'get_cmap'): ColormapRegistry.get_cmap = _stub
    def _stub(self, *a, **kw): return None
    if not hasattr(ScalarMappable, 'norm'): ScalarMappable.norm = _stub
_attach_remaining_stubs()
